<?php
declare(strict_types=1); require_once __DIR__.'/../includes/layout.php'; require_admin();
$rows=db()->query('SELECT rs.*,u.fullname,u.phone,b.title,b.rental_price_per_day FROM reservations rs JOIN users u ON u.id=rs.user_id JOIN books b ON b.id=rs.book_id ORDER BY FIELD(rs.status,"pending","approved","converted","rejected"),rs.created_at DESC')->fetchAll();
page_start('รายการจอง','reservations'); ?>
<div class="page-head"><div><h1>รายการจองออนไลน์</h1><p>ตรวจสอบคำขอ อนุมัติ และเริ่มการเช่าเมื่อลูกค้ามารับ</p></div></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>ลูกค้า</th><th>หนังสือ</th><th>วันรับ</th><th>กำหนดคืน</th><th>สร้างเมื่อ</th><th>สถานะ</th><th>ดำเนินการ</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r['fullname'])?></b><br><small><?=e($r['phone'])?></small></td><td><?=e($r['title'])?></td><td><?=thai_date($r['pickup_date'])?></td><td><?=thai_date($r['due_date'])?></td><td><?=thai_date($r['created_at'],true)?></td><td><?=status_badge($r['status'],reservation_label($r['status']))?></td><td><form class="actions" method="post" action="<?=base_url('actions/reservation-action.php')?>"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><?php if($r['status']==='pending'):?><button class="btn btn-success" name="action" value="approve">อนุมัติ</button><button class="btn btn-danger" name="action" value="reject" data-confirm="ปฏิเสธรายการจองนี้?">ปฏิเสธ</button><?php elseif($r['status']==='approved'):?><button class="btn btn-primary" name="action" value="convert" data-confirm="ลูกค้ามารับหนังสือแล้วและต้องการเริ่มเช่า?">เริ่มการเช่า</button><?php else:?>—<?php endif?></form></td></tr><?php endforeach?><?php if(!$rows):?><tr><td colspan="7" class="empty">ยังไม่มีรายการจอง</td></tr><?php endif?></tbody></table></div></section>
<?php page_end(); ?>
